object StringsI18n {
    fun get(lang: AppLanguage): Strings {
        val resolved = if (lang == AppLanguage.SYSTEM) {
            when (java.util.Locale.getDefault().language.lowercase()) {
                "in", "id" -> AppLanguage.ID
                "zh" -> AppLanguage.ZH
                "ja" -> AppLanguage.JA
                "ar" -> AppLanguage.AR
                "vi" -> AppLanguage.VI
                "th" -> AppLanguage.TH
                "ko" -> AppLanguage.KO
                "es" -> AppLanguage.ES
                "pt" -> AppLanguage.PT
                "ms" -> AppLanguage.MS
                "hi" -> AppLanguage.HI
                else -> AppLanguage.EN
            }
        } else {
            lang
        }
        return when (resolved) {
            AppLanguage.SYSTEM, AppLanguage.EN -> en
            AppLanguage.ID -> id
            AppLanguage.ZH -> zh
            AppLanguage.JA -> ja
            AppLanguage.AR -> ar
            AppLanguage.VI -> vi
            AppLanguage.TH -> th
            AppLanguage.KO -> ko
            AppLanguage.ES -> es
            AppLanguage.PT -> pt
            AppLanguage.MS -> ms
            AppLanguage.HI -> hi
        }
    }

